#ifndef MEP_OCTAVE_LSP_H
#define MEP_OCTAVE_LSP_H

// The analysis half of mep's own Octave language server (the wire half is
// octave_lsp_server.cpp, the `mep-octave-lsp` binary; the `octave_ls` entry
// in main.cpp's kBuiltinLsp spawns it). Everything here is a pure function
// of the document text, so the whole server is testable without a client
// (octave_lsp_test.cpp). Positions are 0-based lines and 0-based byte
// columns (`positionEncoding: "utf-8"`).
//
// Generated by tools/new_language.py; nix_lsp.h is the worked example of
// every function below.

#include <memory>
#include <string>
#include <vector>

struct OctaveLspRange {
    int line = 0, col = 0, end_line = 0, end_col = 0;
};

class OctaveLspDocument;

/**
 * @brief Parses and analyses a document; every query below runs on the result.
 * @param path The file's path or URI, if known: a classdef must be named after its file.
 */
std::shared_ptr<const OctaveLspDocument> OctaveLspAnalyze(const std::vector<std::string> &lines,
                                                          const std::string &path = std::string());

/** @brief What Octave's `__parse_file__` reports for the text: "ok" or "<msg> near line L, column C". */
std::string OctaveLspOctaveCheck(const std::string &text, const std::string &path);

// --- Diagnostics ------------------------------------------------------------------

enum class OctaveLspSeverity { Error = 1, Warning = 2, Information = 3, Hint = 4 };

struct OctaveLspDiagnostic {
    OctaveLspRange range;
    OctaveLspSeverity severity = OctaveLspSeverity::Error;
    std::string code;  // stable id: syntax-error, ...
    std::string message;
    bool unnecessary = false;  // LSP DiagnosticTag.Unnecessary
    bool deprecated = false;   // LSP DiagnosticTag.Deprecated
};

std::vector<OctaveLspDiagnostic> OctaveLspDiagnostics(const OctaveLspDocument &doc);
/** @brief `path:line:col: severity: message [code]`, 1-based, as `--lint` prints it. */
std::string OctaveLspFormatDiagnostic(const std::string &path, const OctaveLspDiagnostic &d);
/** @brief Whether a diagnostic makes `--lint` exit non-zero (an error or a warning). */
bool OctaveLspDiagnosticFails(const OctaveLspDiagnostic &d);

// --- Completion / hover / signature help -------------------------------------------

enum class OctaveLspKind {
    Text = 1, Method = 2, Function = 3, Field = 5, Variable = 6, Class = 7, Module = 9, Property = 10,
    Value = 12, Keyword = 14, Snippet = 15, Constant = 21, Struct = 22,
};

struct OctaveLspCompletionItem {
    std::string label;
    std::string insert_text;
    OctaveLspKind kind = OctaveLspKind::Text;
    std::string detail;
    std::string documentation;
    int replace_start = 0, replace_end = 0;  // byte columns on the request's line
};

std::vector<OctaveLspCompletionItem> OctaveLspCompletions(const OctaveLspDocument &doc, int line, int col);

struct OctaveLspHoverInfo {
    bool found = false;
    std::string text;  // markdown
    OctaveLspRange range;
};

OctaveLspHoverInfo OctaveLspHover(const OctaveLspDocument &doc, int line, int col);

struct OctaveLspSignatureHelp {
    bool found = false;
    std::string label;
    std::vector<std::string> params;  // substrings of label
    std::string documentation;
    int active_param = 0;
};

OctaveLspSignatureHelp OctaveLspSignatureAt(const OctaveLspDocument &doc, int line, int col);

// --- Navigation -------------------------------------------------------------------------

struct OctaveLspLocation {
    OctaveLspRange range;
};

std::vector<OctaveLspLocation> OctaveLspDefinition(const OctaveLspDocument &doc, int line, int col);

struct OctaveLspReference {
    OctaveLspRange range;
    bool is_definition = false;
};

std::vector<OctaveLspReference> OctaveLspReferences(const OctaveLspDocument &doc, int line, int col);

struct OctaveLspTextEdit {
    OctaveLspRange range;
    std::string new_text;
};

struct OctaveLspRenameTarget {
    bool found = false;
    OctaveLspRange range;
    std::string placeholder;
};

OctaveLspRenameTarget OctaveLspPrepareRename(const OctaveLspDocument &doc, int line, int col);
std::vector<OctaveLspTextEdit> OctaveLspRename(const OctaveLspDocument &doc, int line, int col,
                                               const std::string &new_name, std::string *error);

// --- Outline / folding --------------------------------------------------------------------

enum class OctaveLspSymbolKind {
    File = 1, Module = 2, Namespace = 3, Class = 5, Method = 6, Property = 7, Field = 8, Function = 12,
    Variable = 13, Constant = 14, String = 15, Number = 16, Boolean = 17, Array = 18, Object = 19, Key = 20,
    Null = 21,
};

struct OctaveLspSymbol {
    std::string name;
    std::string detail;
    OctaveLspSymbolKind kind = OctaveLspSymbolKind::Variable;
    OctaveLspRange range;
    OctaveLspRange sel_range;
    int parent = -1;
};

std::vector<OctaveLspSymbol> OctaveLspSymbols(const OctaveLspDocument &doc);

struct OctaveLspFold {
    int start_line = 0, end_line = 0;
    std::string kind;  // "" or "comment"
};

std::vector<OctaveLspFold> OctaveLspFolds(const OctaveLspDocument &doc);

// --- Formatting ------------------------------------------------------------------------------

/** @brief The formatter as one edit over the changed lines; none when already formatted. */
std::vector<OctaveLspTextEdit> OctaveLspFormat(const std::vector<std::string> &lines, int width, std::string *error);

#endif  // MEP_OCTAVE_LSP_H
